CREATE TABLE IF NOT EXISTS local_floaty_windows (long_id TEXT PRIMARY KEY,title TEXT NOT NULL,scope TEXT NOT NULL DEFAULT 'all_pages',route_key TEXT NOT NULL DEFAULT '',x_normalized REAL NOT NULL DEFAULT 1,y_normalized REAL NOT NULL DEFAULT 1,width_px INTEGER NOT NULL DEFAULT 360,height_px INTEGER NOT NULL DEFAULT 420,minimized INTEGER NOT NULL DEFAULT 0,stack_order INTEGER NOT NULL DEFAULT 0,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'active',updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS local_floaty_items (window_long_id TEXT NOT NULL,provider TEXT NOT NULL,record_type TEXT NOT NULL,record_long_id TEXT NOT NULL,view_json TEXT NOT NULL,revision INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'active',updated_at TEXT NOT NULL,PRIMARY KEY(window_long_id,provider,record_type,record_long_id));
